declare const DSH_CONTRACT = "\n\n## DSH \u63D2\u4EF6\u6267\u884C\u5408\u540C\n\n\u672C Skill \u5728 DSH \u4E2D\u7531 Office PPT \u63D2\u4EF6\u6258\u7BA1\u3002\u9075\u5FAA\u4E0A\u9762\u7684\u53D9\u4E8B\u3001\u8BBE\u8BA1\u3001\u6750\u6599\u89E3\u6790\u548C\u9875\u9762\u89C4\u8303\uFF0C\u5E76\u4F7F\u7528\u4E0B\u9762\u7684\u53D7\u63A7\u5165\u53E3\u5B8C\u6210\u6267\u884C\uFF1A\n\n1. Slides \u6A21\u5F0F\u4E0B\u5148\u901A\u8FC7 `skill({\"name\":\"tencent-pptx\"})` \u52A0\u8F7D\u672C Skill\uFF1B\u540C\u4E00\u8F6E\u6210\u529F\u52A0\u8F7D\u540E\uFF0C\u6E32\u67D3\u5DE5\u5177\u624D\u4F1A\u653E\u884C\u3002\u7528\u6237\u663E\u5F0F\u8F93\u5165 `/tencent-pptx` \u5177\u6709\u76F8\u540C\u6548\u529B\u3002PPT \u6A21\u5F0F\u5C5E\u4E8E\u72EC\u7ACB\u7684 Kimi-compatible PPTD \u94FE\u8DEF\uFF0C\u4E0D\u8C03\u7528\u672C Skill\u3002\n2. \u6709\u53C2\u8003\u6750\u6599\u65F6\u5148\u9605\u8BFB `references/create-from-material.md`\uFF0C\u5B8C\u6210\u6750\u6599\u62C6\u89E3\uFF0C\u518D\u9605\u8BFB\u5E76\u6267\u884C `references/create-from-scratch.md`\u3002\u65E0\u53C2\u8003\u6750\u6599\u65F6\u76F4\u63A5\u6267\u884C create-from-scratch\u3002\n3. \u4F7F\u7528\u5E26\u6E90\u9875\u7D22\u5F15\u7684 Slides \u6A21\u677F\u65F6\uFF0C\u5148\u8C03\u7528 `ppt_list_templates` \u5E76\u4F20\u5165 `workflow: \"slides\"`\uFF0C\u518D\u8C03\u7528 `ppt_get_template_pages` \u83B7\u53D6\u5168\u90E8\u6E90\u9875\u7684\u8BED\u4E49\u76EE\u5F55\u548C\u9010\u9875\u7B80\u5316\u8BF4\u660E\u3002\u6309\u7167\u6BCF\u4E2A\u8F93\u51FA\u9875\u7684\u53D9\u4E8B\u4EFB\u52A1\u9009\u62E9\u6E90\u6A21\u677F\u9875\uFF0C\u5E76\u518D\u6B21\u8C03\u7528 `ppt_get_template_pages` \u8BFB\u53D6\u6240\u9009\u6E90\u9875\u7684 SlideP JSX \u7ED3\u6784\u53C2\u8003\u3002\u6BCF\u4E2A\u8F93\u51FA\u9875\u90FD\u8981\u5728 STORY.md \u548C DESIGN.md \u4E2D\u8BB0\u5F55\u6E90\u9875\u7F16\u53F7\u3001\u9009\u62E9\u7406\u7531\u548C\u91C7\u7528\u7684\u7B80\u5316\u65B9\u5F0F\u3002\n5. \u6267\u884C\u672C Skill \u81EA\u52A8\u9644\u52A0\u7684 `ppt-template-fidelity` \u89C4\u5219\uFF0C\u628A\u6E90\u9875\u7684\u6807\u9898\u533A\u3001\u5185\u5BB9\u5206\u7EC4\u3001\u4E3B\u89C6\u89C9\u3001\u4E3B\u8981\u8272\u5757\u3001\u524D\u666F/\u80CC\u666F\u914D\u8272\u548C\u6BD4\u4F8B\u5173\u7CFB\u843D\u5B9E\u5230 DESIGN.md \u4E0E\u6700\u7EC8 JSX\u3002\u8BED\u4E49\u7248\u5F0F\u951A\u70B9\u4FDD\u7559\u8FC7\u534A\uFF1B\u7A7A Box \u548C\u91CD\u590D\u88C5\u9970\u4E0D\u8BA1\u5206\u3002\u5185\u5BB9\u8D85\u51FA\u6E90\u9875\u5BB9\u91CF\u65F6\u6539\u9009\u66F4\u5339\u914D\u7684\u6E90\u9875\u3002\n6. \u5728\u8C03\u7528\u751F\u6210\u5DE5\u5177\u4E4B\u524D\uFF0C\u4E00\u6B21\u6027\u5F62\u6210 STORY.md\u3001DESIGN.md\u3001\u9875\u9762\u5143\u6570\u636E\u548C\u5168\u90E8\u53D7\u9650 JSX\u3002\u4EE5\u6240\u9009\u6E90\u6A21\u677F\u9875\u7684 JSX \u7ED3\u6784\u4E3A\u7248\u5F0F\u8D77\u70B9\uFF0C\u5728\u7EE7\u627F\u533A\u57DF\u5185\u66FF\u6362\u5F53\u524D\u5185\u5BB9\u548C\u6570\u636E\uFF1B\u7CBE\u7B80\u4F18\u5148\u538B\u7F29\u6587\u6848\u4E0E\u8F85\u52A9\u8BF4\u660E\uFF0C\u5E76\u6309\u9010\u9875\u7B80\u5316\u8BF4\u660E\u4FDD\u7559\u6E90\u9875\u5206\u7EC4\u3001\u4FE1\u606F\u5C42\u7EA7\u3001\u9605\u8BFB\u987A\u5E8F\u548C\u6807\u5FD7\u8272\u533A\u57DF\u3002\u9875\u9762\u6587\u4EF6\u6309 `slide_01_<slug>.jsx`\u3001`slide_02_<slug>.jsx` \u987A\u5E8F\u547D\u540D\uFF1B\u6BCF\u4E2A\u9875\u9762\u53EA\u6709\u4E00\u4E2A `<Slide>` \u6839\u8282\u70B9\u3002\u53EF\u4F7F\u7528\u672C Skill \u8BB0\u5F55\u7684 SlideP \u7EC4\u4EF6\u3001\u5185\u8054 SVG\u3001\u5B57\u9762\u91CF\u5C5E\u6027\u548C\u5BF9\u5B57\u9762\u91CF\u6570\u7EC4\u7684\u5C40\u90E8 `map`\u3002\u7981\u6B62 import\u3001require\u3001\u4E00\u822C\u53D8\u91CF\u3001\u4EFB\u610F\u51FD\u6570\u6216\u8C03\u7528\u3001\u5916\u90E8\u8D44\u6E90 URL\u3001\u4E8B\u4EF6\u5904\u7406\u5668\u548C JSX spread\u3002\n7. \u63D0\u4EA4\u524D\u5BF9\u7167\u6E90\u9875\u505A\u56DB\u9879 review\uFF1A\u6574\u4F53\u8F6E\u5ED3\u4E0E\u5206\u7EC4\u3001\u7B2C\u4E00\u89C6\u89C9\u4E0E\u4FE1\u606F\u5C42\u7EA7\u3001\u524D\u666F/\u80CC\u666F\u914D\u8272\u5173\u7CFB\u3001\u5185\u5BB9\u662F\u5426\u81EA\u7136\u88C5\u5165\u3002\u4EFB\u4E00\u7EF4\u5EA6\u4E0D\u5408\u7406\u65F6\uFF0C\u8C03\u6574\u73B0\u6709\u6709\u610F\u4E49\u533A\u57DF\u6216\u6539\u9009\u6E90\u9875\u3002\u65B0\u589E\u7A7A\u6846\u3001\u590D\u5236\u88C5\u9970\u548C\u51D1\u539F\u59CB shape \u6570\u91CF\u5747\u4E0D\u5F97\u4F5C\u4E3A\u4FEE\u6B63\u65B9\u5F0F\u3002\n8. \u9875\u9762\u9700\u8981\u56FE\u7247\u65F6\uFF0C\u5148\u7528\u5F53\u524D DSH \u4F1A\u8BDD\u91CC\u771F\u5B9E\u53EF\u7528\u7684\u751F\u56FE\u6216\u56FE\u7247\u68C0\u7D22\u5DE5\u5177\u628A\u6587\u4EF6\u4FDD\u5B58\u5230\u5DE5\u4F5C\u533A\uFF0C\u518D\u5728 `ppt_create.assets` \u4E2D\u4F20\u5165 `source_path` \u4E0E\u5B89\u5168\u82F1\u6587\u6587\u4EF6\u540D\u3002JSX \u901A\u8FC7 `resources/images/<file_name>` \u5F15\u7528\u3002\u6CA1\u6709\u53EF\u7528\u751F\u56FE\u5DE5\u5177\u65F6\uFF0C\u4F7F\u7528\u4E0D\u4F9D\u8D56\u56FE\u7247\u7684\u8868\u8FBE\u65B9\u6848\u3002\u7981\u6B62\u7559\u4E0B `image://generate` \u6216 `image://search` \u5360\u4F4D\u7B26\u3002\n9. \u7528 `ppt_create` \u63D0\u4EA4\u5B8C\u6574\u9879\u76EE\u3002\u5E26\u6E90\u9875\u7D22\u5F15\u7684\u6A21\u677F\u8981\u6C42\u6BCF\u4E2A\u9875\u9762\u540C\u65F6\u4F20\u5165 `template_page_number` \u548C `template_reference_rationale`\u3002\u63D2\u4EF6\u8D1F\u8D23\u9A8C\u8BC1\u6E90\u6A21\u677F\u9875\u6620\u5C04\u3001\u8FC7\u534A\u8BED\u4E49\u7248\u5F0F\u951A\u70B9\u3001\u9009\u4E2D\u6A21\u677F\u6807\u5FD7\u8272\u533A\u57DF\u3001\u6DF1\u8272\u586B\u5145\u533A\u6587\u5B57\u6781\u6027\u3001\u6E90\u9875\u4E3B\u89C6\u89C9\u5360\u6BD4\u3001\u5B89\u5168\u5199\u5165\u9879\u76EE\u76EE\u5F55\u3001\u9759\u6001 JSX\u3001\u9010\u9875 `slidep-validate`\u3001Tencent Docs editor_sdk\u3001SlideP \u9996\u8F6E\u540C\u6B65\u3001PPTX \u4FDD\u5B58\u3001\u5BA1\u8BA1\u3001\u4E0B\u8F7D\u548C\u53EA\u8BFB\u4EA4\u4ED8\u9884\u89C8\u3002\u7981\u6B62\u4ECE Bash \u76F4\u63A5\u8FD0\u884C SlideP \u6216 editor_sdk\u3002\n10. \u5DE5\u5177\u5931\u8D25\u65F6\uFF0C\u6839\u636E\u660E\u786E\u7684\u9875\u9762\u3001\u8D44\u6E90\u6216\u8FD0\u884C\u65F6\u8BCA\u65AD\u4FEE\u6B63\u8F93\u5165\u3002\u751F\u6210\u540E\u5728\u5BF9\u8BDD\u91CC\u7FFB\u9875\u68C0\u67E5\u53EA\u8BFB\u9884\u89C8\uFF1B\u9700\u8981\u7EE7\u7EED\u4FEE\u6539\u65F6\uFF0C\u901A\u8FC7\u4EA7\u51FA\u7269\u5361\u6253\u5F00\u5DE5\u4F5C\u533A PPTX\u3002\u5B8C\u6574\u751F\u6210\u540E\u4E0D\u56DE\u9000\u4FEE\u6539 JSX\u3002\n";
